function minimumReplacement(nums) {
  let operations = 0;
  let bound = nums[nums.length - 1];

  for (let i = nums.length - 2; i >= 0; i--) {
    const value = nums[i];
    if (value <= bound) {
      bound = value;
      continue;
    }
    const pieces = Math.ceil(value / bound);
    operations += pieces - 1;
    bound = Math.floor(value / pieces);
  }
  return operations;
}

