function minimumReplacement(nums) {
  // Try every way to cut each element: k pieces whose smallest (leftmost) piece is m.
  const memo = new Map();
  const solve = (index, limit) => {
    if (index < 0) return 0;
    const key = index + ',' + limit;
    if (memo.has(key)) return memo.get(key);
    const whole = nums[index];
    let best = Infinity;
    for (let k = 1; k <= whole; k++) {
      for (let m = 1; m * k <= whole; m++) {
        if (m > limit) break;
        if (whole - m > (k - 1) * limit) continue;
        best = Math.min(best, k - 1 + solve(index - 1, m));
      }
    }
    memo.set(key, best);
    return best;
  };
  return solve(nums.length - 1, nums[nums.length - 1]);
}

