function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'small') {
    const n = pick(1, 6);
    const top = pick(1, 4) === 1 ? 5 : 24;
    const nums = Array.from({ length: n }, () => pick(1, top));
    if (rand() < 0.2) nums.sort((a, b) => a - b);
    if (rand() < 0.2) nums.sort((a, b) => b - a);
    return [nums];
  }
  const n = pick(1500, 2000);
  const mode = pick(0, 2);
  const top = mode === 0 ? 1000000000 : mode === 1 ? 1000 : 50;
  const nums = Array.from({ length: n }, () => pick(1, top));
  if (mode === 2) nums.sort((a, b) => b - a);
  // A tiny last element forces huge splits, so the answer passes 2^31.
  if (mode === 0) nums[n - 1] = pick(1, 3);
  return [nums];
}
